export const faultStepHeight=s=>s.fault?.stage20?(s.fault.stepHeight??.36):.24;
import {BODIES,perimeter,portSegment} from './architecture.js';
import {toWorld} from './pose.js';
export const CLIMB_LIMITS={height:6,gap:1.5,edgeReach:.95,sweepStep:.035,speed:2.8};
const normal={N:[0,-1],S:[0,1],E:[1,0],W:[-1,0]},dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);
function closest(e,p,margin=0){const x=e.b.x-e.a.x,z=e.b.z-e.a.z,len=Math.hypot(x,z),m=Math.min(.49,margin/len),t=Math.max(m,Math.min(1-m,((p.x-e.a.x)*x+(p.z-e.a.z)*z)/(len*len)));return{x:e.a.x+t*x,z:e.a.z+t*z};}
export function faultAnchors(s){if(s.fault?.climbAnchors)return s.fault.climbAnchors;const out=[];for(const b of BODIES){const pose=s.positions[b.id],add=(l,kind,y,key)=>{const n=normal[l.face],origin=toWorld(pose,{x:0,z:0}),direction=toWorld(pose,{x:n[0],z:n[1]}),a=toWorld(pose,{x:l.a[0],z:l.a[1]}),bb=toWorld(pose,{x:l.b[0],z:l.b[1]});out.push({body:b.id,kind,y,key,a,b:bb,n:{x:direction.x-origin.x,z:direction.z-origin.z}});};for(const e of perimeter(b))add(e,'roof',pose.y+6,b.id+':roof:'+out.length);for(const p of b.ports)if(s.fault.openPorts.includes(b.id+':'+p.id))add({...portSegment(b,p,0),face:p.face},'frame',pose.y+.16,b.id+':'+p.id);}return out;}
function landing(world,e,at){const p={x:at.x-e.n.x*.65,z:at.z-e.n.z*.65,y:e.y-.16+.05},support=world.support(p,.1);if(!support||support.owner!==e.body||e.kind==='roof'&&support.kind!=='roof')return null;p.y=support.y-.16;return world.clear(p)?p:null;}
export function clearClimbPath(world,path){let checks=0;for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],n=Math.max(1,Math.ceil(dist(a,b)/CLIMB_LIMITS.sweepStep));for(let j=0;j<=n;j++){const t=j/n;if(!world.clear({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,z:a.z+(b.z-a.z)*t}))return{ok:false,checks};checks++;}}return{ok:true,checks};}
export function findFaultClimbs(s,fresh=false){const m=s.fault?.motion;if(!s.fault?.climbEnabled||!m||m.control!=='walk'||m.climbMove||!m.world.support(s.player,.03))return{};const p=s.player,world=m.world,key=[s.fault.climbHeight??6,faultStepHeight(s),p.x,p.y,p.z,p.yaw,p.pitch].map(n=>n.toFixed(3)).join(',');if(!fresh&&m.queryCache?.world===world&&m.queryCache.key===key)return m.queryCache.targets;const cache=m.anchorCache;if(!cache||cache.world!==world)m.anchorCache={world,rows:faultAnchors(s)};const edges=m.anchorCache.rows,owner=m.ownerAt(p.x,p.z,p.y),sources=edges.filter(e=>(owner===e.body&&e.kind==='frame'||owner==='roof:'+e.body&&e.kind==='roof')&&Math.abs(e.y-(p.y+.16))<.05&&Math.hypot(p.x-closest(e,p).x,p.z-closest(e,p).z)<=CLIMB_LIMITS.edgeReach),ranked=[];
 for(const e of edges){const delta=e.y-(p.y+.16);if(Math.abs(delta)<=faultStepHeight(s)||Math.abs(delta)>(s.fault.climbHeight??CLIMB_LIMITS.height)+.00003)continue;const at=closest(e,p,.5),dx=at.x-p.x,dz=at.z-p.z,flat=Math.hypot(dx,dz);if(flat>3.2||flat<.01)continue;const dy=e.y-(p.y+1.81),cosPitch=Math.cos(p.pitch),dot=(dx*Math.sin(p.yaw)*cosPitch+dz*Math.cos(p.yaw)*cosPitch+dy*Math.sin(p.pitch))/Math.hypot(flat,dy);if(dot<.45||(dx*Math.sin(p.yaw)+dz*Math.cos(p.yaw))/flat<.4)continue;
 for(const source of sources){const sa=closest(source,at,.05),gap=Math.hypot(sa.x-at.x,sa.z-at.z);if(gap>CLIMB_LIMITS.gap+.00001)continue;const end=landing(world,e,at);if(!end)continue;const up=delta>0,outer=up?{x:at.x+e.n.x*(s.fault.stage19?.5:.4),z:at.z+e.n.z*(s.fault.stage19?.5:.4)}:{x:sa.x+source.n.x*(s.fault.stage19?.5:.4),z:sa.z+source.n.z*(s.fault.stage19?.5:.4)},high=Math.max(p.y,end.y)+.005,path=up?[{...p},{...outer,y:p.y},{...outer,y:high},{...end,y:high},end]:[{...p},{...outer,y:high},{...outer,y:end.y},end];ranked.push({kind:up?'up':'down',target:e.key,body:e.body,anchor:e.kind,height:Math.abs(delta),gap,score:dot*10-flat*.2,path,end,source:source.key});}}
 const result={};for(const c of ranked.sort((a,b)=>b.score-a.score)){if(result[c.kind])continue;const sweep=clearClimbPath(world,c.path);if(sweep.ok)result[c.kind]={...c,checks:sweep.checks};}m.queryCache={world,key,targets:result};return result;
}
export function startFaultClimb(m,kind){if(m.climbMove)return false;const c=findFaultClimbs(m.sim,true)[kind];if(!c){m.sim.message='昇降先なし：縁に近づき、対象へ視点を向けてください（6m・縁間1.5m以内）。';return false;}m.climbMove={...c,index:1,world:m.world};m.vy=0;m.vx=0;m.vz=0;m.axis=0;m.grounded=false;m.gapHold=false;m.sim.message=(kind==='up'?'登る':'降りる')+'：'+c.target+' / 高低差'+c.height.toFixed(2)+'m・縁間'+c.gap.toFixed(2)+'m';return true;}
export function tickFaultClimb(m,dt){const c=m.climbMove,p=m.sim.player;let left=Math.min(.1,dt)*CLIMB_LIMITS.speed;while(c&&left>1e-8&&c.index<c.path.length){const target=c.path[c.index],d=dist(p,target),step=Math.min(d,left),t=d<1e-10?1:step/d,q={x:p.x+(target.x-p.x)*t,y:p.y+(target.y-p.y)*t,z:p.z+(target.z-p.z)*t};if(c.world!==m.world||!m.world.clear(q)){m.climbMove=null;m.sim.message='昇降を停止：経路の障害物または形状変更。';return;}Object.assign(p,q);left-=step;if(d<=step+1e-8)c.index++;}if(c.index>=c.path.length){m.climbMove=null;m.grounded=!!m.world.support(p,.03);m.sim.message='昇降完了：'+c.target;}p.owner=m.ownerAt(p.x,p.z,p.y);m.eyeY=p.y;}

export function climbDiagnosis(s){if(!s.fault?.motion)return '';const p=s.player,w=s.fault.motion.world,max=s.fault.climbHeight??6;const rows=faultAnchors(s).map(e=>{const at=closest(e,p,.5),dx=at.x-p.x,dz=at.z-p.z;return{e,at,d:Math.hypot(dx,dz),f:(dx*Math.sin(p.yaw)+dz*Math.cos(p.yaw))/(Math.hypot(dx,dz)||1)};}).filter(r=>r.f>.4&&r.d<4&&Math.abs(r.e.y-p.y-.16)>faultStepHeight(s)).sort((a,b)=>{const score=r=>{const dy=r.e.y-p.y-1.81,dx=r.at.x-p.x,dz=r.at.z-p.z;return 10*(dx*Math.sin(p.yaw)*Math.cos(p.pitch)+dz*Math.cos(p.yaw)*Math.cos(p.pitch)+dy*Math.sin(p.pitch))/Math.hypot(r.d,dy)-r.d*.2;};return score(b)-score(a);});const valid=Object.values(findFaultClimbs(s)),r=rows.find(r=>valid.some(c=>c.target===r.e.key))??rows[0];if(!r)return '対象なし：実在する縁へ近づき視点を向けてください';const delta=r.e.y-p.y-.16,floor=!!landing(w,r.e,r.at),hasFloor=w.support({x:r.at.x-r.e.n.x*.65,z:r.at.z-r.e.n.z*.65,y:r.e.y-.11},.1)?.owner===r.e.body,ok=Object.values(findFaultClimbs(s)).some(c=>c.target===r.e.key);const owner=s.fault.motion.ownerAt(p.x,p.z,p.y),sources=faultAnchors(s).filter(e=>(owner==='roof:'+e.body&&e.kind==='roof'||owner===e.body&&e.kind==='frame')&&Math.abs(e.y-p.y-.16)<.05&&Math.hypot(p.x-closest(e,p).x,p.z-closest(e,p).z)<=.95),gap=Math.min(...sources.map(e=>{const q=closest(e,r.at);return Math.hypot(q.x-r.at.x,q.z-r.at.z);})),dy=r.e.y-p.y-1.81,dx=r.at.x-p.x,dz=r.at.z-p.z,dot=(dx*Math.sin(p.yaw)*Math.cos(p.pitch)+dz*Math.cos(p.yaw)*Math.cos(p.pitch)+dy*Math.sin(p.pitch))/Math.hypot(r.d,dy),reason=ok?'昇降可':!sources.length?'現在の縁に届かない':Math.abs(delta)>max?'高さ超過':gap>1.5?'水平ずれ超過':!hasFloor?'着地点床なし':!floor?'身体空間不足':dot<.45?'視線角度':'途中経路に障害物';return r.e.key+' / '+r.e.kind+' 高低差'+delta.toFixed(3)+'m / 縁間'+(Number.isFinite(gap)?gap.toFixed(2):'未検出')+'m / 上限'+max+'m / 床'+(hasFloor?'あり':'なし')+' / '+reason;}
